callback_with_context.context_function_id:
(confirmation = Component("C471BB49-B4A9-4A84-A78C887C2F7B6A8A")) => { 
 DoIf(
  self.CurrentState != "inactive" && IsPanelOpen("diplomacy_dropdown") == false, 
   confirmation.PropagateContext(this);
   confirmation.SetVisible(true)
 )
}

#propagate the CcoBuildingSetRecord#
( building_cco = GetIfElse(IsContextValid(ConstructionItemContext), ConstructionItemContext.BuildingLevelRecordContext, GetIfElse(IsContextValid(LifecycleStateContext), LifecycleStateContext.NextBuildingLevelContext, BuildingContext.BuildingLevelRecordContext)) ) =>
{
 GetIfElse( IsContextValid(building_cco), building_cco.BuildingChainRecordContext.BuildingSetContext, PossibleBuildingSetList.Filter(Key == "wh3_dlc29_set_vmp_lair_secondary_followers").FirstContext )
}

( slot = StoredContextFromParent("CcoCampaignBuildingSlot") ) =>
{
 GetIfElse( IsBuiltInSlot(slot), "complete", "default" )
}
